def detailed__dict__(obj, ignore_private_variables=True, ignore_keys=
    frozenset(), include_keys=None):
    """
    Get the dictionary representation of an object, including private variables if specified.

    Args:
        obj: The object to convert to dictionary
        ignore_private_variables: If True, ignore private variables (starting with underscore)
        ignore_keys: Set of keys to ignore
        include_keys: Set of keys to include (if not None, only these keys will be included)

    Returns:
        dict: Dictionary representation of the object
    """
    if include_keys is not None:
        include_keys = set(include_keys)

    # Handle enum objects specially
    if hasattr(obj, '__class__') and hasattr(obj.__class__, '__members__'):
        # For enums, we want to include the special attributes
        ignore_keys = ignore_keys.union({'name', 'value'})
        # For enums, we also need to handle the __objclass__ attribute
        ignore_keys = ignore_keys.union({'__objclass__'})

    # Handle objects with __dict__
    if hasattr(obj, '__dict__'):
        result = {}
        for key, value in obj.__dict__.items():
            # Skip private variables if requested
            if ignore_private_variables and key.startswith('_') and not key.startswith('__'):
                if key not in ignore_keys:
                    continue
            # Skip ignored keys
            if key in ignore_keys:
                continue
            # Handle include_keys filtering
            if include_keys is not None and key not in include_keys:
                continue
            result[key] = value
        return result
    else:
        # For non-class objects, return empty dict or handle appropriately
        return {}
